import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const screensDir = join(root, 'screens');
const docsDir = join(root, 'docs');
rmSync(screensDir, { recursive: true, force: true });
rmSync(docsDir, { recursive: true, force: true });
mkdirSync(screensDir, { recursive: true });
mkdirSync(docsDir, { recursive: true });

const icon = (name) => `<svg class="ico-svg"><use href="#i-${name}"/></svg>`;
const ph = (label = '') => `<div class="ph p-media">${label ? `<span>${label}</span>` : ''}</div>`;
const top = (title, action = '') => `<header class="p-top"><strong>${title}</strong><div>${action}</div></header>`;
const back = (title) => `<header class="navbar"><div class="nav-leading"><button class="btn-plain tap" data-back aria-label="Назад"><svg class="ios-back" viewBox="0 0 12 21" fill="none"><path d="M10.25 1.75L1.75 10.5l8.5 8.75" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div><div class="title">${title}</div></header>`;
const tabs = (active) => `<nav class="tabbar p-tabs" aria-label="Основная навигация">${[['feed','house','Лента'],['cookings','calendar','Готовим'],['recipes','bookmark','Рецепты'],['profile','user','Профиль']].map(([id,i,label])=>`<button class="tab tap${active===id?' is-on':''}" data-go="${id}" aria-label="${label}"${active===id?' aria-current="page"':''}><span class="ico">${icon(i)}</span><span>${label}</span></button>`).join('')}</nav>`;
const shell = (id, title, body, { tab = false, action = '', dark = false } = {}) => `<div class="screen p-page${dark?' p-dark':''}" id="scr-${id}">${title ? back(title) : ''}<main class="body-scroll p-scroll">${!title ? top(id==='feed'?'Подача':id==='cookings'?'Готовим вместе':id==='recipes'?'Рецепты':id==='profile'?'Профиль':'Подача',action) : ''}${body}</main>${tab?tabs(id):''}<div class="home-ind"></div></div>`;
const row = (i,t,s,attrs='') => `<button class="p-row tap" ${attrs}><span class="p-row-icon">${icon(i)}</span><span><b>${t}</b><small>${s}</small></span>${icon('chevron-right')}</button>`;
const note = (key, text) => `<div class="p-note" data-show-denied="${key}">${icon('info')}<span>${text}</span></div>`;
const author = (name, meta, relation='') => `<div class="p-author"><div class="p-avatar ph"></div><span><b>${name}</b>${relation?`<em>${relation}</em>`:''}<small>${meta}</small></span><button class="p-icon tap" data-toast="Скрыть · Пожаловаться · Скопировать ссылку">${icon('ellipsis')}</button></div>`;
const actions = (likes, cooked, save='Сохранить') => `<div class="p-actions"><button class="tap">${icon('heart')}<span>${likes}</span></button><button class="tap" data-go="cookalong">${icon('chef-hat')}<span>${cooked}</span></button><button class="tap p-save" data-toast="Сохранено в рецепты">${icon('bookmark')}<span>${save}</span></button></div>`;
const cardPost = (name, meta, text, mediaLabel, likes, cooked, relation='') => `<article class="p-card">${author(name,meta,relation)}<p class="p-post-text">${text}</p>${ph(mediaLabel)}${actions(likes,cooked)}</article>`;

